T = [
    ['doodh', 'double roti', 'anday'],
    ['doodh', 'chai patti'],
    ['doodh', 'double roti', 'chai patti', 'cheeni'],
    ['double roti', 'anday'],
    ['doodh', 'double roti', 'chai patti'],
]

def support(transactions, itemset):
    count = 0
    for transaction in transactions:
        has_all = True
        for item in itemset:
            if item not in transaction:
                has_all = False
                break
        if has_all:
            count = count + 1
    total = len(transactions)
    if total == 0:
        return 0.0
    support_value = count / total
    return round(support_value, 2)

def rule_metrics(transactions, lhs, rhs):
    support_lhs = support(transactions, lhs)
    support_rhs = support(transactions, rhs)
    support_lhs_rhs = support(transactions, lhs + rhs)
    if support_lhs == 0.0:
        confidence = 0.0
        lift = 0.0
    else:
        confidence = support_lhs_rhs / support_lhs
        lift = confidence / support_rhs if support_rhs != 0.0 else 0.0
    return (round(support_lhs_rhs, 2), round(confidence, 2), round(lift, 2))

print(rule_metrics(T, ['doodh'], ['double roti']))

